<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const api = async (url, options) => {
      const response = await fetch(url, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const element = (tag, text) => {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      return node;
    };

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        const project = await api(`/api/projects/${match[1]}`);
        const back = element('button', 'Projects');
        back.type = 'button';
        back.addEventListener('click', () => { location.href = '/'; });
        const heading = element('h1', project.name);
        const form = element('form');
        const input = element('input');
        input.type = 'text';
        input.setAttribute('aria-label', 'Task title');
        const create = element('button', 'Create task');
        create.type = 'submit';
        form.append(input, create);
        const alert = element('p');
        alert.setAttribute('role', 'alert');
        alert.hidden = true;
        const filterLabel = element('label', 'Task filter');
        const filter = element('select');
        filter.setAttribute('aria-label', 'Task filter');
        for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value));
        filterLabel.append(filter);
        const tasks = element('section');
        tasks.className = 'task-list';
        tasks.setAttribute('aria-label', 'Tasks');
        const refresh = async () => {
          const items = await api(`/api/projects/${match[1]}/tasks`);
          tasks.replaceChildren(...items.filter(task => filter.value === 'All' || (filter.value === 'Completed') === task.completed).map(task => {
            const row = element('div');
            row.dataset.testid = 'task-row';
            const checkbox = element('input');
            checkbox.type = 'checkbox';
            checkbox.checked = task.completed;
            checkbox.setAttribute('aria-label', `Complete ${task.title}`);
            checkbox.addEventListener('change', async () => {
              await api(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
              await refresh();
            });
            row.append(checkbox, element('span', task.title));
            return row;
          }));
        };
        filter.addEventListener('change', refresh);
        form.addEventListener('submit', async event => {
          event.preventDefault();
          const title = input.value.trim();
          if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
          try {
            await api(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
            input.value = ''; alert.hidden = true; await refresh();
          } catch (error) { alert.textContent = error.message; alert.hidden = false; }
        });
        app.replaceChildren(back, heading, form, alert, filterLabel, tasks);
        await refresh();
        return;
      }

      const heading = element('h1', 'Workboard');
      const form = element('form');
      const input = element('input');
      input.type = 'text';
      input.name = 'name';
      input.setAttribute('aria-label', 'Project name');
      input.autocomplete = 'off';
      const create = element('button', 'Create project');
      create.type = 'submit';
      form.append(input, create);
      const alert = element('p');
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      const list = element('section');
      list.className = 'project-list';
      list.setAttribute('aria-label', 'Projects');

      form.addEventListener('submit', async event => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        create.disabled = true;
        try {
          await api('/api/projects', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name })
          });
          input.value = '';
          alert.hidden = true;
          await renderProjects(list);
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        } finally { create.disabled = false; }
      });
      app.replaceChildren(heading, form, alert, list);
      await renderProjects(list);
    }

    async function renderProjects(list) {
      const projects = await api('/api/projects');
      const rows = projects.map(project => {
        const row = element('div');
        row.dataset.testid = 'project-row';
        row.append(element('span', project.name));
        const open = element('button', 'Open project');
        open.type = 'button';
        open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
        row.append(open);
        return row;
      });
      list.replaceChildren(...rows);
    }

    render().catch(() => {
      app.replaceChildren(element('h1', 'Workboard'), element('p', 'Unable to load Workboard.'));
    });
  </script>
</body>
